def c6():
    for i, (lex, items) in enumerate(NAT):
        for _, a, b in items:
            assert A.taut(a, b)[1] == A.taut(a, b)[2]
        cond = (f"{PRE} {STAR_RULES} {RULES} {lex} Запишите каждое рассуждение в виде формулы $x \\vdash y$ (кванторы — по $a$ и $b$), приведите к виду "
                "$x^* \\vdash y^*$ и исследуйте по правилам приложения, тавтология ли формула.\n\n" + H.series([t for t, _, _ in items]))
        ans = "; ".join(f"{H.letters(j)}) ${F(a, b)}$ — {'тавтология' if A.taut(a, b)[0] else 'не тавтология'}" for j, (_, a, b) in enumerate(items))
        sol = " ".join(f"{H.letters(j)}) {H.explain(a, b)[1]}" for j, (_, a, b) in enumerate(items))
        card(5, "T", "vary", cond, ans, sol, "с. 192–194, Приложение", ["приписывание значений", "тавтология, D1", "перевод"], form="nat")


