# ================================================================ E1. разрешимость S⁶_cq (ст. 5)
def e1():
    items = [(C(Al(x), Al(y, "b")), Al(Al(x), "b")), (W(Al(x), Al(y)), Al(W(x, y))), (W(Al(x), y), Al(x))]
    res = []
    for a, b in items:
        r = A.taut(a, b)
        assert r[1] == r[2]
        res.append(r[0])
    st = [(Al(Ex(W(N(x), x), "b")), True), (Ex(Al(C(W(x, y), N(x)), "b")), False)]
    cond = (f"{PRE} {RULES} {S6} D2 (с. 194): $\\vdash x$ — тавтология, если и только если $x$ — тавтология; MT3 (с. 195): $(K^1a^1) \\ldots (K^na^n)x$ — "
            "тавтология, если и только если $x$ — тавтология. Пользуясь процедурой разрешимости $S^6_{cq}$ (с. 196), установите доказуемость в $S^6_{cq}$ "
            "каждой формулы и обоснуйте.\n\n" + H.series([f"${F(a, b)}$" for a, b in items] + [f"${F(s)}$" for s, _ in st]))
    ans = "; ".join(f"{H.letters(i)}) {'доказуема' if t else 'недоказуема'}" for i, t in enumerate(res + [t for _, t in st]))
    sol = ("Процедура (с. 196): для $x \\vdash y$ — выяснить, тавтология ли она (MT5, MT6); для $\\vdash x$ — свести к формулам представительства, т. е. к "
           "тавтологичности $x$ (D2, MT7, MT8). " + " ".join(f"{H.letters(i)}) {H.explain(a, b)[1]} Значит, {'доказуема (MT6)' if t else 'недоказуема (MT5)'}."
                                                            for i, ((a, b), t) in enumerate(zip(items, res))) +
           " г) $(\\forall a)(\\exists b)(\\sim x \\vee x)$: по MT3 тавтология, так как $\\sim x \\vee x$ — тавтология; по D2 $\\vdash$ этой формулы — тавтология, "
           "по MT8 доказуема. д) $(\\exists a)(\\forall b)((x \\vee y)\\sim x)$: матрица $(x \\vee y)\\sim x$ ложна при $x = 0$, $y = 0$; по MT3 не тавтология, по D2 "
           "формула не тавтология, по MT7 недоказуема.")
    card(5, "C", "iso", cond, ans, sol, "с. 194–196, Приложение, MT3, MT5–MT8, D2", ["приписывание значений", "разрешимость", "S6cq"], system="S^6_cq")

    items = [(Al(C(x, y)), Al(x)), (Ex(x), Al(x)), (Al(x), W(Al(x), C(y, N(y))))]
    res = [A.taut(a, b) for a, b in items]
    assert all(r[1] == r[2] for r in res)
    cond = (f"{PRE} {RULES} {S6} Для каждой формулы установите доказуемость в $S^6_{{cq}}$; для доказуемой назовите метатеорему, которая это гарантирует, "
            "для недоказуемой — вариант приписывания, при котором формула принимает 0.\n\n" + H.series([f"${F(a, b)}$" for a, b in items]))
    ans = "; ".join(f"{H.letters(i)}) {'доказуема (MT6)' if r[0] else 'недоказуема (MT5)'}" for i, r in enumerate(res))
    sol = " ".join(f"{H.letters(i)}) {H.explain(a, b)[1]}" for i, (a, b) in enumerate(items)) + \
        " В) содержит в заключении $y$, отсутствующее в посылке, — это и есть «дополнительный случай» доказательства MT6 (с. 195)."
    sol = sol.replace(" В) ", " в) ")
    card(5, "C", "iso", cond, ans, sol, "с. 192–196, Приложение, MT5, MT6", ["приписывание значений", "разрешимость", "S6cq"], system="S^6_cq")


# ================================================================ E2, E3. метатеоремы (ст. 8–9)
def e23():
    card(8, "M", "vary", f"""MT2 (с. 195): высказывание $(\\forall a)x$ — тавтология, если и только если $x$ — тавтология; аналогично для $(\\exists a)x$. В книге MT3 — «высказывание $(K^1a^1) \\ldots (K^na^n)x$ есть тавтология, если и только если $x$ есть тавтология» — сопровождается пометкой «следует из MT2». Проведите это доказательство подробно.""",
         "Индукцией по $n$: при $n = 1$ это MT2; если утверждение верно для $n - 1$ кванторных групп, то $(K^1a^1)[(K^2a^2) \\ldots (K^na^n)x]$ по MT2 тавтология "
         "тогда и только тогда, когда тавтология $(K^2a^2) \\ldots (K^na^n)x$, а это по предположению — когда тавтология $x$.",
         "Обозначим $u_k = (K^ka^k) \\ldots (K^na^n)x$, $u_{n+1} = x$. Для каждого $k$ высказывание $u_k$ имеет вид $(\\forall a^k)u_{k+1}$ или $(\\exists a^k)u_{k+1}$; по MT2 "
         "(с. 195) $u_k$ — тавтология $\\Leftrightarrow$ $u_{k+1}$ — тавтология. Цепочка эквивалентностей $u_1 \\Leftrightarrow u_2 \\Leftrightarrow \\ldots \\Leftrightarrow u_{n+1}$ "
         "(индукция по числу групп) даёт MT3. Ни одна из групп не должна быть особой: MT2 сформулирована для любого $x$ и любого квантора.",
         "с. 195, Приложение, MT2, MT3", ["приписывание значений", "метатеорема"], form="meta", answer="proof")

    taut(Al(x), W(Al(x), C(N(y), y)), True)
    card(8, "M", "vary", f"""{S6} По образцу доказательства MT6 (с. 195–196: если $x \\vdash y$ тавтология и в $y$ есть элементарные высказывания, отсутствующие в $x$, то тавтологией будет $x \\vee \\sim zz \\vdash y$, где $z$ — высказывание, содержащее все такие элементарные высказывания; она доказуема в силу полноты $S^s_{{cq}}$, а $x \\vdash x \\vee \\sim zz$ доказуема в силу $S^6$; по транзитивности доказуема $x \\vdash y$) проведите доказательство доказуемости в $S^6_{{cq}}$ формулы $(\\forall a)x \\vdash (\\forall a)x \\vee \\sim yy$ ($x, y$ — высказывания, $a$ входит в $x$): назовите $z$, обе формулы цепочки и основания каждого шага.""",
         "$z = y$. 1) $(\\forall a)x \\vdash (\\forall a)x \\vee \\sim yy$ доказуема в силу $S^6$ — это уже искомая формула; цепочка вырождается: вторая формула "
         "$(\\forall a)x \\vee \\sim yy \\vdash (\\forall a)x \\vee \\sim yy$ доказуема в $S^s_{cq}$ (заключение не содержит новых высказываний); транзитивность.",
         "Формула — тавтология (посылке 1: $x = 1$ по правилу 2; в заключении $(\\forall a)x$ получает 1 по правилу 4 — заключение 1; со стороны заключения: заключение 0 — "
         "$(\\forall a)x = 0$ в заключении, $x$ можно приписать 0, по правилу 5 и посылка 0; D1). В $y$-части есть $y$, отсутствующее в посылке, — случай MT6. "
         "Берём $z = y$ (содержит все отсутствующие в посылке элементарные высказывания). Шаг 1: $(\\forall a)x \\vdash (\\forall a)x \\vee \\sim yy$ — «доказуема в силу "
         "$S^6$» (с. 196). Шаг 2: $(\\forall a)x \\vee \\sim yy \\vdash (\\forall a)x \\vee \\sim yy$ — в заключении нет высказываний, отсутствующих в посылке; это тавтология, "
         "по полноте $S^s_{cq}$ доказуема. Шаг 3: правило транзитивности. Пример показывает, что $x \\vee \\sim zz$ из доказательства MT6 — именно та «добавка», "
         "которой не может дать $S^s_{cq}$ сама.",
         "с. 195–196, Приложение, MT6", ["приписывание значений", "метатеорема", "S6cq"], form="meta", answer="proof", system="S^6_cq")

    card(9, "M", "vary", f"""{S6} D2 (с. 194): $\\vdash x$ — тавтология, если и только если $x$ — тавтология. MT1 (с. 195): высказывание — тавтология, если и только если тавтологии все формулы его представительства. Докажите: формула $\\vdash x$ доказуема в $S^6_{{cq}}$, если и только если в $S^6_{{cq}}$ доказуемы все формулы представительства $x$.""",
         "$\\vdash x$ доказуема $\\Rightarrow$ тавтология (MT7) $\\Rightarrow$ $x$ тавтология (D2) $\\Rightarrow$ формулы представительства — тавтологии (MT1) $\\Rightarrow$ "
         "доказуемы (MT6); обратно: формулы доказуемы $\\Rightarrow$ тавтологии (MT5) $\\Rightarrow$ $x$ тавтология (MT1) $\\Rightarrow$ $\\vdash x$ тавтология (D2) $\\Rightarrow$ доказуема (MT8).",
         "Необходимость. Пусть $\\vdash x$ доказуема в $S^6_{cq}$. По MT7 (с. 196) она тавтология, по D2 (с. 194) $x$ — тавтология, по MT1 (с. 195) тавтологии все формулы "
         "его представительства (формулы вида $\\sim c \\vdash d$, D3), по MT6 (с. 195) каждая доказуема в $S^6_{cq}$. Достаточность. Пусть все формулы представительства "
         "доказуемы. По MT5 они тавтологии, по MT1 $x$ — тавтология, по D2 тавтология и $\\vdash x$, по MT8 она доказуема. Это обоснование пункта 2 процедуры "
         "разрешимости $S^6_{cq}$ (с. 196): вопрос о доказуемости $\\vdash x$ сводится к доказуемости формул представительства.",
         "с. 194–196, Приложение, D2, MT1, MT5–MT8", ["приписывание значений", "метатеорема", "S6cq"], form="meta", answer="proof", system="S^6_cq")

    card(9, "M", "vary", f"""{TERMS} {S6} {DI} {DR} Докажите: 1) всякая формула, доказуемая в $S^6_{{cq}}$, и всякая формула переименования доказуемы в $S^r$; 2) при этом в $S^r$ доказуемы и некоторые формулы, не доказуемые ни в $S^6_{{cq}}$, ни в $S^i$ (приведите пример со ссылкой на книгу). {AK}""",
         "1) Для $x \\vdash y$ из $S^6_{cq}$ возьмём $v = y$: $y \\vdash y$ — формула переименования (замена нуля вхождений, $D^i$); для формулы переименования — "
         "$v = x$: $x \\vdash x$ в $S^i$. 2) $(\\forall a)(a \\leftarrow c) \\vdash (b \\leftarrow c)$ — аксиома $A^k$ (п. 2 $D^r$); в $S^6_{cq}$ она недоказуема (с. 196), в $S^i$ — нет (не переименование).",
         "1) $D^i$ (с. 197) допускает замену нуля вхождений, поэтому $u \\vdash u$ доказуема в $S^i$ для любого $u$. Если $x \\vdash y$ доказуема в $S^6_{cq}$, то пара "
         "$x \\vdash y$ (в $S^6_{cq}$), $y \\vdash y$ (в $S^i$) удовлетворяет п. 1 $D^r$. Если $x \\vdash y$ — формула переименования, годится пара $x \\vdash x$, $x \\vdash y$ "
         "(обе в $S^i$). 2) $(\\forall a)(a \\leftarrow c) \\vdash (b \\leftarrow c)$: $y$ получается из $(a \\leftarrow c)$ заменой свободного $a$ на $b$, вхождений с "
         "кванторной группой по $b$ нет — аксиома $A^k$, доказуема в $S^r$ по п. 2. На с. 196 сказано, что в $S^6_{cq}$ не доказуема формула $(\\forall a)P(a) \\vdash P(b)$ "
         "этого вида; это и не формула переименования: заключение не начинается с кванторной группы, а $(b \\leftarrow c) \\ne (\\forall a)(a \\leftarrow c)$. Такие формулы "
         "книга называет смешанными (с. 197).",
         "с. 196–197, Приложение, D^i, D^r, A^k", ["приписывание значений", "метатеорема", "Sr"], form="meta", answer="proof", system="S^r")


# ================================================================ E4. диагностика о системах (ст. 6)
def e4():
    card(6, "E", "open", f"""{S6} Студент пишет: «По MT6 в $S^6_{{cq}}$ доказуемы все общезначимые формулы классического исчисления предикатов, записанные как $x \\vdash y$. Поэтому $S^6_{{cq}}$ эквивалентна классическому исчислению предикатов, и, в частности, в ней доказуема формула $(\\forall a)P(a) \\vdash P(b)$». Найдите все ошибки и сошлитесь на книгу.""",
         "MT6 говорит о тавтологиях в смысле D1 приложения, а не об общезначимых формулах; по с. 196 $S^6_{cq}$ ещё не эквивалентна классическому исчислению: "
         "$(\\forall a)P(a) \\supset P(b)$ общезначима, но не тавтология, и $(\\forall a)P(a) \\vdash P(b)$ в $S^6_{cq}$ недоказуема. Эквивалентна система $S^k$ (MT9, MT10).",
         "MT6 (с. 195): «если $x \\vdash y$ есть тавтология, то она доказуема в $S^6_{cq}$» — тавтология по D1 (с. 193). С. 196: «наше определение тавтологии не совпадает "
         "с определением общезначимой формулы»; пример — $(\\forall a)P(a) \\supset P(b)$; «в $S^6_{cq}$ не будут доказуемы формулы $(\\forall a)P(a) \\vdash P(b)$ и "
         "$\\vdash (\\forall a)P(a) \\supset P(b)$». Эквивалентность классическому исчислению — у $S^k$ (схемы $A^k$; MT9, MT10, с. 196–197).",
         "с. 195–197, Приложение, MT6, MT9, MT10", ["приписывание значений", "S6cq", "диагностика"], form="meta", system="S^6_cq")

    card(6, "E", "open", f"""Доказательство MT6 (с. 195–196) разбирает случай, когда $x \\vdash y$ — тавтология, а в $y$ есть элементарные высказывания, отсутствующие в $x$. Студент излагает его так: «Берём высказывание $z$, составленное из элементарных высказываний посылки $x$. Тогда $x \\vee \\sim zz \\vdash y$ — тавтология и доказуема в силу полноты $S^6_{{cq}}$, а $x \\vdash x \\vee \\sim zz$ доказуема по правилу подстановки; отсюда доказуема $x \\vdash y$». Найдите все ошибки.""",
         "$z$ должно содержать все элементарные высказывания, которые входят в $y$ и отсутствуют в $x$; $x \\vee \\sim zz \\vdash y$ доказуема в силу полноты $S^s_{cq}$ "
         "(ссылка на полноту доказываемой системы $S^6_{cq}$ — порочный круг); $x \\vdash x \\vee \\sim zz$ доказуема в силу $S^6$, а итог получается по правилу транзитивности.",
         "С. 195: «где $z$ есть любое высказывание, содержащее все те элементарные высказывания, которые входят в $y$ и отсутствуют в $x$. Но в силу полноты $S^s_{cq}$ "
         "формула $x \\vee \\sim zz \\vdash y$ доказуема в $S^6_{cq}$, а формула $x \\vdash x \\vee \\sim zz$ доказуема в силу $S^6$. Отсюда по правилу транзитивности…» "
         "(с. 196). Ошибки студента: 1) выбор $z$ из высказываний посылки (тогда в заключении остались бы новые высказывания); 2) ссылка на полноту $S^6_{cq}$ — именно её "
         "доказывает MT6; 3) «правило подстановки» вместо $S^6$ и транзитивности.",
         "с. 195–196, Приложение, MT6", ["приписывание значений", "метатеорема", "диагностика"], form="meta", system="S^6_cq")


# ================================================================ F. Aᵏ, Dⁱ, Dʳ (ст. 4–8)
def els(*ts):
    return EL(*ts)


def f1():
    sets = [
        [(Al(W(els("a", "c"), els("a", "d"))), W(els("b", "c"), els("b", "d"))),
         (Al(C(els("a", "c"), Ex(els("a", "b"), "b"))), C(els("b", "c"), Ex(els("b", "b"), "b"))),
         (Al(C(els("a", "c"), els("a", "d"))), C(els("b", "c"), els("a", "d"))),
         (W(els("b", "c"), els("b", "d")), Ex(W(els("a", "c"), els("a", "d")))),
         (Al(W(els("a", "c"), Al(els("a", "d")))), W(els("b", "c"), Al(els("a", "d")))),
         ],
        [(Al(C(els("c", "a"), N(els("a", "d")))), C(els("c", "e"), N(els("e", "d")))),
         (C(els("e", "c"), Ex(els("e", "b"), "b")), Ex(C(els("a", "c"), Ex(els("a", "b"), "b")))),
         (C(els("b", "c"), Ex(els("b", "b"), "b")), Ex(C(els("a", "c"), Ex(els("a", "b"), "b")))),
         (Al(Ex(els("a", "b"), "b")), Ex(els("b", "b"), "b")),
         (Al(W(N(els("a", "c")), Ex(els("a", "d")))), W(N(els("d", "c")), Ex(els("a", "d")))),
         ],
    ]
    for lv, its in enumerate(sets):
        res = [bool(H.is_ak(p, q)) for p, q in its]
        cond = (f"{TERMS} {AK} Для каждой формулы установите, есть ли она аксиома $A^k$; для аксиомы укажите $x$, $a$, $b$ и вид схемы, для неаксиомы — "
                "нарушенное условие.\n\n" + H.series([f"${F(p, q)}$" for p, q in its]))
        ans = "; ".join(f"{H.letters(i)}) {'аксиома' if r else 'не аксиома'}" for i, r in enumerate(res))
        expl = []
        for i, ((p, q), r) in enumerate(zip(its, res)):
            if r:
                kq, a_, b_ = H.is_ak(p, q)[0]
                body = p[2] if kq == "all" else q[2]
                expl.append(f"{H.letters(i)}) схема {'$(\\forall a)x \\vdash y$' if kq == 'all' else '$y \\vdash (\\exists a)x$'}: $x = {T(body)}$, свободные "
                            f"вхождения ${a_}$ заменены на ${b_}$, кванторных групп по ${b_}$ со свободным ${a_}$ внутри нет")
            else:
                expl.append(f"{H.letters(i)}) {why_not_ak(p, q)}")
        sol = "С. 196. " + "; ".join(expl) + "."
        card(4, "R", "iso", cond, ans, sol, "с. 196, Приложение, A^k", ["приписывание значений", "Sk", "аксиомы"], system="S^k")


def why_not_ak(p, q):
    for kq, f, g in (("all", p, q), ("ex", q, p)):
        if f[0] != kq:
            continue
        a_, body = f[1], f[2]
        for b_ in "bcde":
            if b_ != a_ and H.subst_free(body, a_, b_) == g:
                return (f"замена ${a_}$ на ${b_}$ делает свободное вхождение ${a_}$ связанным: в $x$ есть кванторная группа по ${b_}$, в области которой ${a_}$ "
                        "входит свободно — условие схемы нарушено")
    return "$y$ не получается из $x$ заменой всех свободных вхождений $a$ одним термином (часть вхождений не заменена или заменены связанные)"


def f2():
    sets = [
        [(Al(W(els("a", "c"), N(els("a", "d")))), Al(W(els("b", "c"), N(els("b", "d"))), "b")),
         (Al(W(els("a", "c"), N(els("a", "d")))), Al(W(els("b", "c"), N(els("a", "d"))), "b")),
         (Ex(C(els("a", "c"), els("a", "b"))), Ex(C(els("b", "c"), els("b", "b")), "b")),
         (C(Al(els("a", "c")), Ex(els("a", "d"))), C(Al(els("a", "c")), Ex(els("e", "d"), "e"))),
         (Al(Ex(C(els("a", "b"), els("b", "c")), "b")), Al(Ex(C(els("a", "e"), els("e", "c")), "e"))),
         ],
        [(Al(Ex(els("a", "b"), "b")), Al(Ex(els("e", "b"), "b"), "e")),
         (Al(Ex(els("a", "b"), "b")), Al(Ex(els("a", "e"), "e"), "c")),
         (Al(Ex(els("a", "b"), "b")), Al(Ex(els("c", "e"), "e"), "c")),
         (W(Al(els("a", "c")), Al(els("a", "d"))), W(Al(els("b", "c"), "b"), Al(els("b", "d"), "b"))),
         (Al(els("a", "c")), Ex(els("b", "c"), "b")),
         ],
        [(N(Ex(N(els("a", "d")))), N(Ex(N(els("c", "d")), "c"))),
         (N(Ex(N(els("a", "d")))), N(Ex(N(els("e", "d")), "e"))),
         (Ex(Al(W(els("a", "b"), els("b", "a")), "b")), Ex(Al(W(els("c", "b"), els("b", "c")), "b"), "c")),
         (Ex(Al(W(els("a", "b"), els("b", "a")), "b")), Ex(Al(W(els("a", "d"), els("d", "a")), "d"))),
         (Ex(Al(W(els("a", "b"), els("b", "a")), "b")), Ex(Al(W(els("b", "b"), els("b", "b")), "b"), "b")),
         ],
    ]
    for its in sets:
        res = [H.is_renaming(p, q) for p, q in its]
        assert len(set(res)) == 2
        cond = (f"{TERMS} {DI} Для каждой формулы установите, доказуема ли она в $S^i$: для формулы переименования укажите заменённые вхождения и новые "
                "термины, для остальных — нарушенное условие $D^i$.\n\n" + H.series([f"${F(p, q)}$" for p, q in its]))
        ans = "; ".join(f"{H.letters(i)}) {'доказуема' if r else 'недоказуема'}" for i, r in enumerate(res))
        sol = "С. 197, $D^i$. " + "; ".join(f"{H.letters(i)}) {why_ren(p, q, r)}" for i, ((p, q), r) in enumerate(zip(its, res))) + "."
        card(5, "C", "iso", cond, ans, sol, "с. 197, Приложение, D^i", ["приписывание значений", "Si", "переименование"], system="S^i")


def why_ren(p, q, ok):
    if ok:
        return "заключение получается из посылки заменой кванторных групп с заменой всех вхождений старого термина в области на новый, не входивший в неё"

    def find(f, g):
        if f == g:
            return None
        if f[0] in ("all", "ex") and g[0] == f[0]:
            if f[1] != g[1]:
                a_, b_, zz = f[1], g[1], f[2]
                if b_ in H.terms_of(zz):
                    return f"новый термин ${b_}$ уже входит в $z = {T(zz)}$"
                if H.subst_all(zz, a_, b_) != g[2] and not H.is_renaming(H.subst_all(zz, a_, b_), g[2]):
                    return f"в $z = {T(zz)}$ заменены не все вхождения ${a_}$ на ${b_}$"
            return find(f[2], g[2])
        if f[0] == g[0] and f[0] in ("conj", "wdis"):
            for u, w in zip(f[1], g[1]):
                r = find(u, w)
                if r:
                    return r
        if f[0] == g[0] == "neg":
            return find(f[1], g[1])
        return "заключение отличается от посылки не только заменой кванторных групп (меняется вид кванторной группы или строение высказывания)"
    return find(p, q) or "условие $D^i$ нарушено"


